896: fn bind_placement(
897:     base: &impl RewardClaimBase,
898:     placement: &CandidatePlacement,
899: ) -> Result<(BoundCell, u64), UnboundReason> {
900:     let id = placement
901:         .crystal_unique_id
902:         .ok_or(UnboundReason::NoCrystalUniqueId)?;
903:     let cell = placement.cell.ok_or(UnboundReason::CellOutOfBounds)?;
904:     let tile = base
905:         .tile(cell.x, cell.y, cell.floor)
906:         .ok_or(UnboundReason::NoEntry)?;
907:     let top_level = tile.depths().iter().filter(|depth| **depth == 0).count();
908:     let mut found = None;
909:     for ordinal in 0..top_level {
910:         let ordinal = u8::try_from(ordinal).map_err(|_| UnboundReason::NoEntry)?;
911:         let Some(entry) = tile.unique(ordinal) else {
912:             continue;
913:         };
914:         if u64::from(entry.unique) != id {
915:             continue;
916:         }
917:         if found.replace((ordinal, entry)).is_some() {
918:             return Err(UnboundReason::AmbiguousEntry);
919:         }
920:     }
921:     let (ordinal, entry) = found.ok_or(UnboundReason::NoEntry)?;
922:     if entry.appearance.map(u64::from) != Some(placement.appearance) {
923:         return Err(UnboundReason::AppearanceMismatch);
924:     }
925:     let key =
926:         bundle::placement_key(cell.floor, cell.x, cell.y, ordinal).ok_or(UnboundReason::NoEntry)?;
927:     Ok((cell, key))
928: }

