335:     pub fn use_key(&self, key: u64, expected_revision: u64, action: u16) -> Option<DoorUse> {
336:         let door = self.find(key)?;
337:         let current = door.state.load(Ordering::Acquire);
338:         if current >> 2 != expected_revision {
339:             return Some(DoorUse::Stale);
340:         }
341:         if action == 0
342:             || door.action != Some(action)
343:             || door.required_level.is_some()
344:             || door.required_storage.is_some()
345:             || door.key_forms.is_none()
346:         {
347:             return Some(DoorUse::Locked);
348:         }
349:         let revision = (current >> 2)
350:             .checked_add(1)
351:             .filter(|r| *r <= u64::MAX >> 2)?;
352:         let opening = current & 3 == 2;
353:         let next = (revision << 2) | if opening { 1 } else { 2 };
354:         Some(
355:             match door
356:                 .state
357:                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
358:             {
359:                 Ok(_) => {
360:                     self.version.fetch_add(1, Ordering::AcqRel);
361:                     DoorUse::Toggled {
362:                         revision,
363:                         open: opening,
364:                     }
365:                 }
366:                 Err(_) => DoorUse::Stale,
367:             },
368:         )
369:     }
370: }
